public void dispatch(CharSequence value, TagValueConsumer consumer) throws InvalidValueException {
		Validity validity = validities.get(this);
		if (validity == null) {
			consumer.acceptOther(this, value);
		} else {
			if (validity.isValid(value)) {
				consumer.dispatch(value, consumer);
			} else {
				throw new InvalidValueException(this, value);
			}
		}
	}

	public Validity getValidity() {
		return validities.get(this);
	}

