off_answer:
public void dispatch(FixTag tag, TagValueConsumer consumer) throws InvalidValueException {
	Validity validity = validities.get(tag);
	if (validity != null) {
		if (validity.isValid()) {
			consumer.dispatch(tag, consumer);
		} else {
			throw new InvalidValueException(tag, tag.getValue());
		}
	} else {
		consumer.dispatch(tag, consumer);
	}
}
